window.AC_ortSuche=function(q,max){
  q=(q||'').trim().toLowerCase();
  if(q.length<2) return [];
  var D=window.AC_STAEDTE, res=[];
  function norm(s){return s.toLowerCase()
    .replace(/ä/g,'a').replace(/ö/g,'o').replace(/ü/g,'u').replace(/ß/g,'ss')
    .replace(/é|è|ê|ë/g,'e').replace(/á|à|â/g,'a').replace(/í|ì/g,'i')
    .replace(/ó|ò|ô/g,'o').replace(/ú|ù/g,'u').replace(/ç/g,'c').replace(/ñ/g,'n');}
  var qn=norm(q);
  for(var i=0;i<D.c.length;i++){
    var c=D.c[i], n1=norm(c[0]), n2=c[5]?norm(c[5]):'';
    var rang=-1;
    if(n1===qn||n2===qn) rang=0;
    else if(n1.indexOf(qn)===0 || (n2 && n2.indexOf(qn)===0)) rang=1;
    else if(n1.indexOf(qn)>0 || (n2 && n2.indexOf(qn)>0)) rang=4;
    if(rang>=0){ res.push({r:rang,i:i,c:c}); if(res.length>1500) break; }
  }
  res.sort(function(a,b){return a.r-b.r || a.i-b.i;});
  return res.slice(0,max||8).map(function(x){
    return {name:(x.c[5]||x.c[0]), alt:(x.c[5]?x.c[0]:null), land:D.l[x.c[1]],
            lat:x.c[2]/1000, lon:x.c[3]/1000, tz:D.tz[x.c[4]]};
  });
};
window.AC_offset=function(tz,y,mo,d,h,mi){
  try{
    var utc=Date.UTC(y,mo-1,d,h,mi);
    var dtf=new Intl.DateTimeFormat('en-US',{timeZone:tz,hour12:false,
      year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'});
    function versatz(ms){
      var p=dtf.formatToParts(new Date(ms)),o={};
      p.forEach(function(x){o[x.type]=x.value;});
      var alsUTC=Date.UTC(+o.year,+o.month-1,+o.day,(o.hour==='24'?0:+o.hour),+o.minute,+o.second);
      return (alsUTC-ms)/3600000;
    }
    var off=versatz(utc);
    off=versatz(utc-off*3600000);
    return off;
  }catch(e){ return null; }
};
